//! Robust multi-load level-set elasticity marquee.
//!
//! Candidate geometry is generated by the existing normalized cantilever
//! descent, but publication is decided only after every candidate is
//! independently replayed under every declared load case.

use fs_cutfem::DesignBoxEdge;
use fs_topols::{
    Cantilever, GridSdf, GuardedSettings, OptimizeSettings, RobustAggregate,
    RobustLoadCase, RobustStop, optimize_compliance_robust_guarded,
};
use std::error::Error;
use std::fs::{File, OpenOptions};
use std::io::{BufWriter, Write};
use std::path::Path;
use std::process::ExitCode;

fn writer(path: &Path) -> std::io::Result<BufWriter<File>> {
    OpenOptions::new().write(true).create_new(true).open(path).map(BufWriter::new)
}

fn parse<T: std::str::FromStr>(args: &[String], index: usize, default: T) -> Result<T, Box<dyn Error>>
where
    T::Err: Error + 'static,
{
    match args.get(index) {
        Some(value) => Ok(value.parse()?),
        None => Ok(default),
    }
}

fn edge(value: &str) -> Result<DesignBoxEdge, Box<dyn Error>> {
    match value.trim().to_ascii_lowercase().as_str() {
        "bottom" => Ok(DesignBoxEdge::Bottom),
        "right" => Ok(DesignBoxEdge::Right),
        "top" => Ok(DesignBoxEdge::Top),
        "left" => Ok(DesignBoxEdge::Left),
        _ => Err(format!("unknown load edge {value:?}; expected bottom/right/top").into()),
    }
}

fn load_cases(path: &Path) -> Result<Vec<RobustLoadCase>, Box<dyn Error>> {
    let text = std::fs::read_to_string(path)?;
    if text.len() > 1_048_576 {
        return Err("load-case CSV exceeds 1 MiB".into());
    }
    let mut cases = Vec::new();
    for (line_index, raw) in text.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let fields: Vec<_> = line.split(',').map(str::trim).collect();
        if fields.len() != 6 {
            return Err(format!(
                "load-case line {} requires edge,start,end,fx,fy,weight",
                line_index + 1
            ).into());
        }
        let start: f64 = fields[1].parse()?;
        let end: f64 = fields[2].parse()?;
        let fx: f64 = fields[3].parse()?;
        let fy: f64 = fields[4].parse()?;
        let weight: f64 = fields[5].parse()?;
        cases.push(RobustLoadCase::new(
            edge(fields[0])?, start, end, [fx, fy], weight
        )?);
        if cases.len() > 64 {
            return Err("at most 64 robust load cases are admitted".into());
        }
    }
    if cases.is_empty() {
        return Err("load-case CSV contains no scenarios".into());
    }
    if !cases.iter().any(|case| case.weight() > 0.0) {
        return Err("at least one robust load case must have positive weight".into());
    }
    Ok(cases)
}

fn numbers(values: &[f64]) -> String {
    let body = values.iter().map(|value| format!("{value:.17e}")).collect::<Vec<_>>().join(",");
    format!("[{body}]")
}

fn run() -> Result<u8, Box<dyn Error>> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if args.len() < 2 || args.len() > 7 {
        return Err(
            "usage: fs-marquee-elasticity-robust OUTPUT_DIR LOAD_CASES.csv [LEVEL=4] [ITERATIONS=12] [VOLFRAC=0.45] [MAX_CANDIDATES=5] [AGGREGATE=worst]"
                .into(),
        );
    }
    let output_dir = Path::new(&args[0]);
    if output_dir.try_exists()? {
        return Err("output directory already exists; refusing to overwrite it".into());
    }
    let cases = load_cases(Path::new(&args[1]))?;
    let level: u32 = parse(&args, 2, 4)?;
    let iterations: usize = parse(&args, 3, 12)?;
    let volfrac: f64 = parse(&args, 4, 0.45)?;
    let max_candidates: usize = parse(&args, 5, 5)?;
    let aggregate = match args.get(6).map(String::as_str).unwrap_or("worst") {
        "sum" | "weighted-sum" => RobustAggregate::WeightedSum,
        "worst" | "worst-weighted" => RobustAggregate::WorstWeightedCase,
        other => return Err(format!("unknown AGGREGATE {other:?}; expected sum or worst").into()),
    };
    if !(2..=7).contains(&level) {
        return Err("LEVEL must lie in [2, 7] for this bounded executable".into());
    }
    if iterations == 0 || iterations > 200 {
        return Err("ITERATIONS must lie in [1, 200]".into());
    }
    if !(volfrac.is_finite() && volfrac > 0.0 && volfrac <= 1.0) {
        return Err("VOLFRAC must lie in (0, 1]".into());
    }
    if !(1..=16).contains(&max_candidates) {
        return Err("MAX_CANDIDATES must lie in [1, 16]".into());
    }

    let n = 1usize << level;
    let mut phi = GridSdf::from_fn(n, &|_, y| (y - 0.5).abs() - 0.42);
    let settings = OptimizeSettings {
        level,
        volfrac,
        iterations,
        move_cells: 0.35,
        nucleation_period: 4,
        hole_radius_cells: 1.5,
        ..OptimizeSettings::default()
    };
    let guarded = GuardedSettings {
        max_candidates,
        contraction: 0.5,
        volume_tolerance: 0.01,
        min_relative_improvement: 0.0,
    };
    // Candidate generation remains the canonical normalized cantilever.
    let driver = Cantilever { load: 1.0, band: 0.125 };
    let report = optimize_compliance_robust_guarded(
        &mut phi, driver, &cases, settings, guarded, aggregate,
    )?;

    std::fs::create_dir(output_dir)?;
    let mut candidates = writer(&output_dir.join("candidates.jsonl"))?;
    for candidate in &report.candidates {
        let evaluation = candidate.evaluation.as_ref().map_or_else(
            || "null".to_string(),
            |state| format!(
                "{{\"objective\":{:.17e},\"weighted_sum_compliance\":{:.17e},\"worst_weighted_compliance\":{:.17e},\"case_compliances\":{},\"volume\":{:.17e},\"snapshot\":\"{:#018x}\"}}",
                state.objective,
                state.weighted_sum_compliance,
                state.worst_weighted_compliance,
                numbers(&state.case_compliances),
                state.volume,
                state.snapshot,
            ),
        );
        let refusal = candidate.refusal.as_ref().map_or_else(
            || "null".to_string(),
            |value| {
                let escaped = value.replace('\\', "\\\\").replace('"', "\\\"");
                format!("\"{escaped}\"")
            },
        );
        writeln!(
            candidates,
            "{{\"index\":{},\"move_cells\":{:.17e},\"volume_feasible\":{},\"improvement_gate\":{},\"robust_evaluation\":{},\"refusal\":{}}}",
            candidate.index,
            candidate.move_cells,
            candidate.volume_feasible,
            candidate.improvement_gate,
            evaluation,
            refusal,
        )?;
    }
    candidates.flush()?;

    let (status, exit) = match report.stop {
        RobustStop::Accepted => ("accepted", 0),
        RobustStop::NoFeasibleCandidate => ("no_feasible_candidate", 10),
        RobustStop::NoImprovingCandidate => ("no_improving_candidate", 11),
        RobustStop::AllCandidatesRefused => ("all_candidates_refused", 12),
    };
    let aggregate_name = match aggregate {
        RobustAggregate::WeightedSum => "weighted_sum",
        RobustAggregate::WorstWeightedCase => "worst_weighted_case",
    };
    let accepted = report.accepted.as_ref().map_or_else(
        || "null".to_string(),
        |state| format!(
            "{{\"objective\":{:.17e},\"weighted_sum_compliance\":{:.17e},\"worst_weighted_compliance\":{:.17e},\"case_compliances\":{},\"volume\":{:.17e},\"snapshot\":\"{:#018x}\"}}",
            state.objective,
            state.weighted_sum_compliance,
            state.worst_weighted_compliance,
            numbers(&state.case_compliances),
            state.volume,
            state.snapshot,
        ),
    );
    let summary = format!(
        "{{\"model\":\"normalized_unit_square_plane_strain_robust_cantilever\",\"authority\":\"estimated\",\"status\":\"{status}\",\"aggregate\":\"{aggregate_name}\",\"load_cases\":{},\"level\":{level},\"iterations\":{iterations},\"volume_limit\":{volfrac:.17e},\"candidate_budget\":{max_candidates},\"baseline_objective\":{:.17e},\"baseline_case_compliances\":{},\"baseline_volume\":{:.17e},\"accepted_move_cells\":{},\"accepted\":{},\"candidate_generation\":\"single canonical downward mid-edge cantilever; robust cases select publication after independent replay\",\"claims\":{{\"simultaneous_multiload_shape_gradient\":false,\"physical_validation\":false,\"kkt_convergence\":false,\"global_optimum\":false,\"three_dimensional\":false}}}}",
        cases.len(),
        report.baseline.objective,
        numbers(&report.baseline.case_compliances),
        report.baseline.volume,
        report.accepted_move_cells.map_or_else(|| "null".to_string(), |value| format!("{value:.17e}")),
        accepted,
    );
    let mut summary_file = writer(&output_dir.join("summary.json"))?;
    writeln!(summary_file, "{summary}")?;
    summary_file.flush()?;

    if report.accepted.is_some() {
        let mut field = writer(&output_dir.join("level-set.csv"))?;
        writeln!(field, "x_normalized,y_normalized,phi_normalized")?;
        for j in 0..=n {
            for i in 0..=n {
                let [x, y] = phi.pos(i, j);
                writeln!(field, "{x:.17e},{y:.17e},{:.17e}", phi.node(i, j))?;
            }
        }
        field.flush()?;
        if let Some(trajectory) = report.trajectory.as_ref() {
            let mut trace = writer(&output_dir.join("trajectory.jsonl"))?;
            for row in &trajectory.rows {
                writeln!(trace, "{row}")?;
            }
            trace.flush()?;
        }
    }

    println!("{summary}");
    Ok(exit)
}

fn main() -> ExitCode {
    match run() {
        Ok(code) => ExitCode::from(code),
        Err(error) => {
            eprintln!("fs-marquee-elasticity-robust: {error}");
            ExitCode::FAILURE
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn unique_file(name: &str) -> std::path::PathBuf {
        std::env::temp_dir().join(format!(
            "frankensim-{name}-{}-{}.csv",
            std::process::id(),
            std::thread::current().name().unwrap_or("test")
        ))
    }

    #[test]
    fn csv_loads_are_independent_and_signed() {
        let path = unique_file("robust-loads");
        std::fs::write(
            &path,
            "# edge,start,end,fx,fy,weight\nright,0.4,0.6,0,-1,0.5\nright,0.4,0.6,0,1,0.5\ntop,0.75,1,1,0,0\n",
        ).unwrap();
        let cases = load_cases(&path).unwrap();
        assert_eq!(cases.len(), 3);
        assert_eq!(cases[0].traction(), [0.0, -1.0]);
        assert_eq!(cases[1].traction(), [0.0, 1.0]);
        assert_eq!(cases[2].weight(), 0.0);
    }

    #[test]
    fn malformed_csv_refuses() {
        let path = unique_file("robust-bad-loads");
        std::fs::write(&path, "right,0.4,0.6,0,-1\n").unwrap();
        assert!(load_cases(&path).is_err());
        let path = unique_file("robust-left-load");
        std::fs::write(&path, "left,0.4,0.6,0,-1,1\n").unwrap();
        assert!(load_cases(&path).is_err());
    }
}
